import './compile-content.mjs';import fs from 'node:fs/promises';const posts=JSON.parse(await fs.readFile('src/lib/content/catalog.json','utf8'));const root='content/series/accessibility';const text='# 웹 접근성 전체 프롬프트 모음집\n\n김장욱 / jangwook.net / '+posts[0].version+' / 2026-10-01\n\n로컬 검토 초안. 실제 성능 검증 및 공개 승인 전입니다.\n\n## 준비와 실행 순서\n\n개요로 평가 범위를 정한 뒤 필요한 기준을 선택합니다. 페이지·상태·입력 방식·브라우저·모델 버전을 기록하고 필요한 DOM·화면·접근성 트리·조작 기록을 준비하세요. 개인정보와 인증 정보는 제거합니다. 판정과 근거를 원본으로 확인한 뒤 개선·재점검으로 연결합니다. 마무리 프롬프트는 실제 도구를 연결한 오케스트레이터의 설계입니다.\n\n'+posts.map(p=>'## '+p.order+'. '+p.title+'\n\n'+p.summary+'\n\n'+p.prompt+'\n\n해설: posts/'+p.slug+'.md\n').join('\n---\n\n');await fs.writeFile(root+'/prompt-collection.draft.md',text);console.log('Review bundle: '+posts.length+' prompts.');